<?php
namespace App\Http\Controllers; use App\Models\{Appointment,Payment,InventoryItem,Staff,Service}; use Illuminate\Http\Request; use Symfony\Component\HttpFoundation\StreamedResponse;
class ReportController extends Controller {
 private function range(Request $r){$from=$r->date('from')??now()->startOfMonth();$to=$r->date('to')??now()->endOfMonth();return [$from,$to];}
 public function index(Request $r){[$from,$to]=$this->range($r);$appointments=Appointment::whereBetween('appointment_date',[$from,$to]);$payments=Payment::whereBetween('created_at',[$from->copy()->startOfDay(),$to->copy()->endOfDay()]);$summary=['appointments'=>(clone $appointments)->count(),'completed'=>(clone $appointments)->where('status','completed')->count(),'cancelled'=>(clone $appointments)->where('status','cancelled')->count(),'revenue'=>(clone $payments)->where('status','paid')->sum('amount'),'lowStock'=>InventoryItem::whereColumn('quantity','<=','reorder_level')->count()];$popular=Service::withCount(['appointments'=>fn($q)=>$q->whereBetween('appointment_date',[$from,$to])->where('status','completed')])->orderByDesc('appointments_count')->limit(8)->get();$staff=Staff::withCount(['appointments'=>fn($q)=>$q->whereBetween('appointment_date',[$from,$to])->where('status','completed')])->get();return view('reports.index',compact('summary','popular','staff','from','to'));}
 public function csv(Request $r):StreamedResponse{[$from,$to]=$this->range($r);$rows=Appointment::with(['client','service','staff'])->whereBetween('appointment_date',[$from,$to])->orderBy('appointment_date')->get();return response()->streamDownload(function()use($rows){$out=fopen('php://output','w');fputcsv($out,['ID','Date','Start','Client','Service','Stylist','Status']);foreach($rows as $a)fputcsv($out,[$a->id,$a->appointment_date->format('Y-m-d'),$a->start_time,$a->client->full_name,$a->service->name,$a->staff->full_name,$a->status]);fclose($out);},'elegance-report-'.$from->format('Ymd').'-'.$to->format('Ymd').'.csv',['Content-Type'=>'text/csv']);}
}
